/* 用户 ios6.css · 糯米机白框全套适配：仅作用于实际私聊、群聊的 sully 钩子。 */
.sully-chat-root{
 --ios6-silver:#e8eaf0;--ios6-blue:#2f81df;
 background-color:#d1d5db!important;
 background-image:repeating-linear-gradient(45deg,#d8dce2,#d8dce2 2px,#cdd1d8 2px,#cdd1d8 4px)!important;
 color:#1a1a1a;
}
.sully-chat-root .sully-chat-header{
 background:linear-gradient(180deg,#b0bccd 0%,#889bb3 50%,#7085a1 51%,#8295ab 100%)!important;
 border-bottom:1px solid #49586d!important;box-shadow:0 1px 3px #0005!important;
}
.sully-chat-root .sully-chat-header .sully-chat-name,
.sully-chat-root .sully-chat-header .sully-chat-status,
.sully-chat-root .sully-chat-header .sully-chat-token{
 color:#fff!important;text-shadow:0 -1px 0 #0009!important;
}
.sully-chat-root .sully-chat-header .sully-chat-back,
.sully-chat-root .sully-chat-header .sully-chat-trigger,
.sully-chat-root .sully-chat-header button[aria-label]{
 background:#0002!important;border:1px solid #0004!important;border-radius:8px!important;
 color:#fff!important;box-shadow:inset 0 1px 0 #fff3,0 1px 2px #0003!important;
}
.sully-chat-root .sully-chat-header button[aria-label] svg{color:#fff!important}
.sully-chat-root .sully-chat-header button[aria-label]:active{background:#0004!important}

/* iOS6 原版冰晶蓝、银灰玻璃气泡：连发气泡按分组圆角连贯显示。 */
.sully-chat-root .sully-bubble-user,
.sully-chat-root .sully-bubble-ai{position:relative!important;overflow:visible!important;z-index:1}
.sully-chat-root .sully-bubble-user{
 background:linear-gradient(180deg,#5da5f5 0%,#2f81df 55%,#1f71d0 100%)!important;
 border:1px solid #1a5bb0!important;color:#fff!important;border-radius:16px 5px 5px 16px!important;
 box-shadow:0 1px 2px #0003,inset 0 1px 0 #ffffff8c!important;text-shadow:0 -1px 0 #0005!important;
}
.sully-chat-root .sully-bubble-ai{
 background:linear-gradient(180deg,#fff 0%,#e8eaf0 60%,#dadde5 100%)!important;
 border:1px solid #b0b6c2!important;color:#1a1a1a!important;border-radius:5px 16px 16px 5px!important;
 box-shadow:0 1px 2px #0002,inset 0 1px 0 #fff!important;text-shadow:0 1px 0 #ffffffe6!important;
}
.sully-chat-root .sully-bubble-user.sully-bubble-group-first{border-radius:16px 16px 5px 16px!important}
.sully-chat-root .sully-bubble-user.sully-bubble-group-last{border-radius:16px 5px 16px 16px!important}
.sully-chat-root .sully-bubble-ai.sully-bubble-group-first{border-radius:16px 16px 16px 5px!important}
.sully-chat-root .sully-bubble-ai.sully-bubble-group-last{border-radius:5px 16px 16px 16px!important}
.sully-chat-root .sully-bubble-user.sully-bubble-group-first.sully-bubble-group-last,
.sully-chat-root .sully-bubble-ai.sully-bubble-group-first.sully-bubble-group-last{border-radius:16px!important}
.sully-chat-root .sully-chat-message [class*="reaction"],
.sully-chat-root .sully-chat-interaction{position:relative;z-index:10}
.sully-chat-root .sully-chat-message-sender{color:#4e5865!important}
.sully-chat-root .sully-bubble-user .sully-chat-reply{background:#ffffff29!important;color:#fff!important;opacity:1!important}
.sully-chat-root .sully-bubble-ai .sully-chat-reply{background:#60708b22!important;color:#344153!important;opacity:1!important}

/* 原版冷灰输入栏与独立的发送/等待状态（不再误伤所有禁用按钮）。 */
.sully-chat-root .sully-chat-inputbar{
 background:linear-gradient(180deg,#d3d7dc,#acb3bd)!important;border-top:1px solid #9198a3!important;
 box-shadow:inset 0 1px 0 #ffffff80!important;
}
.sully-chat-root .sully-chat-input-wrap{
 background:#fff!important;border:1px solid #848b98!important;border-radius:16px!important;
 box-shadow:inset 0 1px 3px #0005,0 1px 0 #fffc!important;
}
.sully-chat-root .sully-chat-textarea{color:#000!important;background:transparent!important;border:0!important;box-shadow:none!important}
.sully-chat-root .sully-chat-actions-button,
.sully-chat-root .sully-chat-input-wrap button{color:#586371!important;filter:drop-shadow(0 1px 0 #fffc)}
.sully-chat-root .sully-chat-send-button:not(:disabled):not([aria-label="停止回复"]){
 background:linear-gradient(180deg,#74a3e2 0%,#3576ce 50%,#1a5ab9 51%,#3b7dda 100%)!important;
 border:1px solid #18417c!important;border-radius:10px!important;color:#fff!important;
 box-shadow:0 1px 1px #0003,inset 0 1px 0 #fff6!important;
}
.sully-chat-root .sully-chat-send-button:disabled,
.sully-chat-root .sully-chat-send-button[aria-label="停止回复"]{
 background:linear-gradient(180deg,#fff 0%,#e2e5eb 50%,#d1d6e0 51%,#e5e8ef 100%)!important;
 border:1px solid #9aa2b0!important;border-radius:10px!important;color:#606875!important;
 box-shadow:0 1px 1px #0002,inset 0 1px 0 #fff!important;
}
/* 保留真正的语音播放、波形与转文字按钮，只有拟物外观变化。 */
.sully-chat-root .sully-voice-bar{
 background:linear-gradient(180deg,#fff,#dfe4eb)!important;border:1px solid #aeb9c8!important;
 color:#344153!important;box-shadow:inset 0 1px 0 #fff,0 1px 2px #0002!important;
}
.sully-chat-root .sully-voice-bar-button{background:linear-gradient(180deg,#fff,#d5dce7)!important;border:1px solid #98a7ba!important;color:#3d618e!important}
.sully-chat-root .sully-voice-bar-transcript{background:#ffffffe6!important;color:#344153!important}

/* 转账：保留 pending、accepted、returned、接收和退回真实逻辑。 */
.sully-chat-root .sully-chat-transfer-card{
 background:linear-gradient(180deg,#86b8f4,#4a91e2 49%,#2374d3 50%,#1a60b4)!important;
 border:1px solid #25568e!important;border-radius:15px!important;
 box-shadow:inset 0 1px 0 #ffffff9e,0 2px 5px #0003!important;color:#fff!important;
}
.sully-chat-root .sully-chat-transfer-card[data-status="accepted"],
.sully-chat-root .sully-chat-transfer-card[data-status="returned"]{filter:saturate(.65)}
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-brand,
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-note,
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-recipient{color:#f3f7ff!important}
.sully-chat-root .sully-chat-transfer-receipt{
 background:linear-gradient(180deg,#fff,#dfe4ec)!important;border:1px solid #adb6c4!important;
 border-radius:12px!important;color:#3a4656!important;box-shadow:inset 0 1px 0 #fff,0 1px 3px #0002!important;
}
.sully-chat-root .sully-chat-transfer-dialog{
 background:linear-gradient(180deg,#fff,#e6eaf1)!important;border:1px solid #9baabc!important;border-radius:17px!important;
}
.sully-chat-root .sully-chat-transfer-dialog>div:first-child{background:linear-gradient(180deg,#b0bccd,#7085a1 52%,#8295ab)!important}
.sully-chat-root .sully-chat-transfer-accept{background:linear-gradient(180deg,#74a3e2,#3576ce 50%,#1a5ab9 51%,#3b7dda)!important;color:#fff!important;border:1px solid #18417c!important}
.sully-chat-root .sully-chat-transfer-return{background:linear-gradient(180deg,#fff,#d8dee8)!important;border:1px solid #aab4c2!important;color:#566273!important}

/* 群聊全局白框沿用界面与气泡，群红包/领取回执套用同一质感。 */
.sully-chat-root.sully-chat-group-root .sully-chat-group-packet{
 background:linear-gradient(180deg,#8cb9ef,#518ed1 49%,#346cae 50%,#23568c)!important;
 border:1px solid #244a77!important;border-radius:14px!important;color:#fff!important;
 box-shadow:inset 0 1px 0 #ffffff80,0 2px 5px #0003!important;
}
.sully-chat-root.sully-chat-group-root .sully-chat-group-packet-receipt{
 background:linear-gradient(180deg,#fff,#dfe4ec)!important;border:1px solid #adb6c4!important;
 border-radius:12px!important;color:#344153!important;box-shadow:inset 0 1px 0 #fff,0 1px 3px #0002!important;
}
.sully-chat-root .sully-chat-message-content{min-width:0;overflow-wrap:anywhere}
